\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{xeCJK}
\setCJKmainfont{SimSun} % 设置中文字体，请根据您的系统调整

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=12cm,
    height=8cm,
    title={近五年我国考研人数变化趋势（2019-2023年）},
    xlabel={年份},
    ylabel={考研人数（万人）},
    xmin=2018.5, xmax=2023.5,
    ymin=200, ymax=500,
    xtick={2019,2020,2021,2022,2023},
    ytick={200,250,300,350,400,450,500},
    legend pos=north west,
    grid=major,
    grid style={dashed,gray!30},
    tick label style={font=\small},
    label style={font=\small},
    title style={font=\large\bfseries},
    x tick label style={/pgf/number format/1000 sep=},
    nodes near coords, % 显示每个点的数值
    every node near coord/.append style={font=\tiny, yshift=-8pt}
]

% 示例数据，请根据实际数据修改
\addplot[color=blue, mark=*, thick] coordinates {
    (2019, 290)
    (2020, 341)
    (2021, 377)
    (2022, 457)
    (2023, 474)
};

\legend{考研人数}

\end{axis}
\end{tikzpicture}
\end{document}
